previewCss:
.darma-loader-darma-b14-golf-putt { --accent: var(--loader-color, #dc2626); --accent-2: var(--loader-secondary-color, #16a34a); width: var(--loader-size, 124px); height: calc(var(--loader-size, 124px) * .6); position: relative; }
.darma-loader-darma-b14-golf-putt::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 22%; border-radius: 40% 40% 4px 4px / 70% 70% 4px 4px; background: linear-gradient(color-mix(in srgb, #fff 24%, var(--accent-2)), var(--accent-2)); }
.darma-loader-darma-b14-golf-putt .darma-loader-darma-b14-golf-putt__flag { position: absolute; bottom: 18%; right: 12%; width: 2.5%; height: 44%; background: #94a3b8; }
.darma-loader-darma-b14-golf-putt .darma-loader-darma-b14-golf-putt__flag::after { content: ''; position: absolute; top: 0; left: 100%; width: 420%; height: 36%; background: var(--accent); clip-path: polygon(0 0, 100% 50%, 0 100%); }
.darma-loader-darma-b14-golf-putt .darma-loader-darma-b14-golf-putt__putter { position: absolute; bottom: 26%; left: 9%; width: 5%; height: 44%; transform-origin: top center; background: linear-gradient(#f1f5f9, #94a3b8); animation: darma-loader-darma-b14-golf-putt-swing-putt calc(var(--loader-speed, 1s) * 2.6) ease-out infinite; }
.darma-loader-darma-b14-golf-putt .darma-loader-darma-b14-golf-putt__putter::after { content: ''; position: absolute; bottom: -4%; left: -70%; width: 240%; height: 13%; border-radius: 2px; background: #64748b; }
.darma-loader-darma-b14-golf-putt span { position: absolute; bottom: 20%; left: 12%; width: calc(var(--loader-size, 124px) * .07); height: calc(var(--loader-size, 124px) * .07); border-radius: 50%; background: radial-gradient(circle at 34% 30%, #fff, #cbd5e1); animation: darma-loader-darma-b14-golf-putt-putt calc(var(--loader-speed, 1s) * 2.6) ease-out infinite; }
@keyframes darma-loader-darma-b14-golf-putt-swing-putt { 0% { transform: rotate(30deg); } 12% { transform: rotate(-22deg); } 26%, 100% { transform: rotate(0deg); } }
@keyframes darma-loader-darma-b14-golf-putt-putt { 0% { opacity: 0; transform: translateX(0); } 8% { opacity: 1; transform: translateX(0); } 14% { transform: translateX(0); } 62% { transform: translateX(calc(var(--loader-size, 124px) * .68)); } 70% { opacity: 0; transform: translateX(calc(var(--loader-size, 124px) * .7)); } 100% { opacity: 0; transform: translateX(calc(var(--loader-size, 124px) * .7)); } }

